# =========================
# 问卷
# =========================

def slider_value_to_number(value):
    try:
        return int(str(value).split()[0])
    except Exception:
        return value


def likert(label, key):
    options = [
        "1 非常不同意",
        "2 不同意",
        "3 有点不同意",
        "4 一般",
        "5 有点同意",
        "6 同意",
        "7 非常同意",
    ]
    st.markdown(f"<div class='survey-question'>{label}</div>", unsafe_allow_html=True)
    value = st.select_slider(" ", options=options, value="4 一般", key=key, label_visibility="collapsed")
    return slider_value_to_number(value)


def frequency_check(label, key):
    options = [
        "1 非常少",
        "2 少",
        "3 有些少",
        "4 适中",
        "5 有些多",
        "6 多",
        "7 非常多",
    ]
    st.markdown(f"<div class='survey-question'>{label}</div>", unsafe_allow_html=True)
    value = st.select_slider(" ", options=options, value="4 适中", key=key, label_visibility="collapsed")
    return slider_value_to_number(value)


def recall_check(label, key):
    options = ["0次", "1次", "2次", "3次", "4次"]
    st.markdown(f"<div class='survey-question'>{label}</div>", unsafe_allow_html=True)
    value = st.select_slider(" ", options=options, value="2次", key=key, label_visibility="collapsed")
    return int(value.replace("次", ""))


def motive_scale(label, key):
    options = [
        "1 完全出于酒店自身利益",
        "2",
        "3",
        "4",
        "5",
        "6",
        "7 完全出于社会责任",
    ]
    st.markdown(f"<div class='survey-question'>{label}</div>", unsafe_allow_html=True)
    value = st.select_slider(" ", options=options, value="4", key=key, label_visibility="collapsed")
    return slider_value_to_number(value)


def render_survey():
    hotel_header()
    show_steps()
    back_button("返回上一页查看")
    st.markdown("### 预订体验问卷")
    st.markdown("请根据刚才的网页浏览与预订体验回答以下问题。")

    mc_frequency = frequency_check("1. 您认为酒店的公益营销活动信息的展示频率如何？", "mc_frequency")
    mc_recall_count = recall_check("2. 您是否还记得在刚才的网页中遇到过几次公益营销界面？", "mc_recall_count")

    reactance_1 = likert("3. 这条酒店网页推送的公益信息限制了我的选择自由。", "reactance_1")
    reactance_2 = likert("4. 这条酒店网页推送的公益信息试图操控我。", "reactance_2")
    reactance_3 = likert("5. 这条酒店网页推送的公益信息似乎替我做了决定。", "reactance_3")
    reactance_4 = likert("6. 这条酒店网页推送的公益信息让我感到有些压力。", "reactance_4")
    reactance_5 = likert("7. 我觉得这条酒店网页推送的公益信息试图支配我的行为。", "reactance_5")
    reactance_6 = likert("8. 我感觉这条酒店网页推送的公益信息想让我按照它的意图去做。", "reactance_6")
    reactance_7 = likert("9. 我感到这条酒店网页推送的公益信息让我被迫采取某种行动。", "reactance_7")

    fit_product = get_fit_product_label()
    fit_1 = likert(f"10. 酒店公益信息提及的{fit_product}，与支持动物救助事业的公益目标很契合。", "fit_1")
    fit_2 = likert(f"11. 酒店公益信息提及的{fit_product}与动物救助事业紧密相连。", "fit_2")
    fit_3 = likert(f"12. 用{fit_product}销售的收益支持动物救助事业，是顺理成章且极为合适的公益举措。", "fit_3")

    altruism_1 = motive_scale("13. 您认为这项公益活动在多大程度上是出于酒店自身利益的动机，还是出于对社会责任的关注？", "altruism_1")
    altruism_2 = motive_scale("14. 您认为这项公益活动在多大程度上是出于追求利润的动机，还是出于社会责任的动机？", "altruism_2")
    altruism_3 = motive_scale("15. 您认为这项公益活动在多大程度上是出于自我导向（利己）的动机，还是出于利他主义的动机？", "altruism_3")

    st.markdown("---")
    st.markdown("<div class='survey-question'>16. 您的出生年份是</div>", unsafe_allow_html=True)
    birth_year = st.number_input(" ", min_value=1940, max_value=date.today().year, value=2000, step=1, key="birth_year", label_visibility="collapsed")
    st.markdown("<div class='survey-question'>17. 您的性别是</div>", unsafe_allow_html=True)
    gender = st.radio(" ", options=["男", "女"], horizontal=True, key="gender", label_visibility="collapsed")

    if not st.session_state.survey_submitted:
        if st.button("提交问卷", type="primary"):
            result = {
                "submit_time": now_china_time_str(),
                "participant_id": st.session_state.participant_id,
                "interface_mode": st.session_state.interface_mode,
                "selected_hotel_name": st.session_state.get("selected_hotel_name", HOTEL_CN),
                "nudge_frequency": st.session_state.nudge_frequency,
                "product_cause_fit": st.session_state.product_cause_fit,
                "altruistic_motivation": st.session_state.altruistic_motivation,
                "nudge_seen": st.session_state.nudge_seen,
                "selected_room": st.session_state.selected_room,
                "room_price": st.session_state.room_price,
                "joined_campaign": st.session_state.cart_campaign_added,
                "campaign_product_name": st.session_state.cart_campaign_name,
                "donation_amount": st.session_state.cart_campaign_price if st.session_state.cart_campaign_added else 0,
                "total_price": total_price(),
                "paid": st.session_state.paid,
                "mc_frequency": mc_frequency,
                "mc_recall_count": mc_recall_count,
                "reactance_1": reactance_1,
                "reactance_2": reactance_2,
                "reactance_3": reactance_3,
                "reactance_4": reactance_4,
                "reactance_5": reactance_5,
                "reactance_6": reactance_6,
                "reactance_7": reactance_7,
                "fit_1": fit_1,
                "fit_2": fit_2,
                "fit_3": fit_3,
                "altruism_1": altruism_1,
                "altruism_2": altruism_2,
                "altruism_3": altruism_3,
                "birth_year": birth_year,
                "gender": gender,
            }
            save_result_to_csv(result)
            save_events_to_csv()
            st.session_state.survey_submitted = True
            st.success("问卷已提交，感谢您的参与！数据已保存。")
            st.rerun()
    else:
        st.success("问卷已提交，感谢您的参与！数据已保存。")
        st.info("如需让下一位参与者在同一实验条件下继续测试，请点击下方按钮。")
        if st.button("开始下一位参与者测试", type="primary"):
            reset_experiment()


# =========================
# 页面分发与后台
# =========================

def render_ota_wrapper():
    stage = st.session_state.stage
    if stage == "浏览首页":
        render_ota_home()
    elif stage == "酒店详情":
        render_ota_detail()
    elif stage == "房型选择":
        render_ota_rooms()
    elif stage == "订单确认":
        render_ota_order()
    elif stage == "支付页面":
        render_ota_payment()
    elif stage == "完成问卷":
        render_survey()


def render_participant_app():
    sync_condition_change()
    stage = st.session_state.stage
    if st.session_state.interface_mode == "OTA界面":
        render_ota_wrapper()
        return
    if stage == "浏览首页":
        render_home()
    elif stage == "酒店详情":
        render_detail()
    elif stage == "房型选择":
        render_rooms()
    elif stage == "订单确认":
        render_order()
    elif stage == "支付页面":
        render_payment()
    elif stage == "完成问卷":
        render_survey()


def make_participant_url():
    mode = "ota" if st.session_state.interface_mode == "OTA界面" else "hotel"
    freq_map = {
        "低频：仅支付前出现1次": "low",
        "中频：浏览与订单阶段出现2次": "medium",
        "三频：浏览、房型与订单阶段出现3次": "three",
        "高频：多阶段重复出现4次": "high",
    }
    fit = "low" if st.session_state.product_cause_fit.startswith("低匹配") else "high"
    motive = "low" if st.session_state.altruistic_motivation.startswith("低利他") else "high"
    freq = freq_map.get(st.session_state.nudge_frequency, "medium")
    return f"?mode={mode}&freq={freq}&fit={fit}&motive={motive}"


def render_admin_panel():
    st.markdown("<div class='main-title'>后台管理页面</div>", unsafe_allow_html=True)
    st.markdown("<div class='sub-title'>本页面用于设置实验条件、预览受试者页面，并下载实验数据。受试者默认不会看到这里。</div>", unsafe_allow_html=True)

    with st.sidebar:
        st.header("后台控制台")
        st.caption("公开测试时，不要把带 ?admin=1 的链接发给受试者。")

        st.session_state.interface_mode = st.selectbox(
            "界面类型",
            ["酒店官网界面", "OTA界面"],
            index=["酒店官网界面", "OTA界面"].index(st.session_state.interface_mode),
        )

        st.session_state.nudge_frequency = st.selectbox(
            "数字助推频率",
            list(DEFAULT_STAGE_MAP.keys()),
            index=list(DEFAULT_STAGE_MAP.keys()).index(st.session_state.nudge_frequency),
        )

        st.session_state.product_cause_fit = st.selectbox(
            "产品-公益匹配度",
            ["高匹配：毛绒公仔 × 濒危动物保护", "低匹配：明信片 × 濒危动物保护"],
            index=["高匹配：毛绒公仔 × 濒危动物保护", "低匹配：明信片 × 濒危动物保护"].index(st.session_state.product_cause_fit),
        )

        st.session_state.altruistic_motivation = st.selectbox(
            "感知利他动机",
            ["高利他动机：全部收益捐出", "低利他动机：公益合作运营推广"],
            index=["高利他动机：全部收益捐出", "低利他动机：公益合作运营推广"].index(st.session_state.altruistic_motivation),
        )

        st.divider()
        st.write("当前阶段：", st.session_state.stage)
        c1, c2 = st.columns(2)
        with c1:
            if st.button("上一步"):
                prev_stage()
                st.rerun()
        with c2:
            if st.button("下一步"):
                next_stage()
                st.rerun()

        if st.button("重置实验", type="secondary"):
            reset_experiment()

        st.divider()
        st.subheader("生成受试者链接")
        participant_query = make_participant_url()
        st.code(participant_query, language="text")
        st.caption("把你的网页基础链接后面接上这段参数，就会打开对应实验条件的受试者页面。")

    tab1, tab2, tab3 = st.tabs(["受试者页面预览", "数据下载", "使用说明"])

    with tab1:
        render_participant_app()

    with tab2:
        st.markdown("### 实验数据")
        if DATA_PATH.exists():
            df = pd.read_csv(DATA_PATH)
            st.dataframe(df, use_container_width=True)
            st.download_button("下载实验结果 CSV", data=DATA_PATH.read_bytes(), file_name="experiment_data.csv", mime="text/csv")

            st.markdown("#### 数据管理")
            st.warning("以下操作会修改服务器端保存的数据，请谨慎使用。")
            delete_rows = st.multiselect("选择要删除的实验数据行号", options=list(df.index), format_func=lambda x: f"第{x + 1}行")
            c_del1, c_del2 = st.columns(2)
            with c_del1:
                if st.button("删除选中实验数据行", disabled=len(delete_rows) == 0):
                    new_df = df.drop(index=delete_rows).reset_index(drop=True)
                    new_df.to_csv(DATA_PATH, index=False, encoding="utf-8-sig")
                    st.success("已删除选中的实验数据行。")
                    st.rerun()
            with c_del2:
                if st.button("清空全部实验数据", type="secondary"):
                    DATA_PATH.unlink(missing_ok=True)
                    st.success("已清空实验数据。")
                    st.rerun()
        else:
            st.info("目前还没有实验结果数据。")

        st.markdown("### 行为日志")
        if EVENT_PATH.exists():
            event_df = pd.read_csv(EVENT_PATH)
            st.dataframe(event_df, use_container_width=True)
            st.download_button("下载行为日志 CSV", data=EVENT_PATH.read_bytes(), file_name="experiment_events.csv", mime="text/csv")

            delete_event_rows = st.multiselect("选择要删除的行为日志行号", options=list(event_df.index), format_func=lambda x: f"第{x + 1}行", key="delete_event_rows")
            c_log1, c_log2 = st.columns(2)
            with c_log1:
                if st.button("删除选中行为日志行", disabled=len(delete_event_rows) == 0):
                    new_event_df = event_df.drop(index=delete_event_rows).reset_index(drop=True)
                    new_event_df.to_csv(EVENT_PATH, index=False, encoding="utf-8-sig")
                    st.success("已删除选中的行为日志行。")
                    st.rerun()
            with c_log2:
                if st.button("清空全部行为日志", type="secondary"):
                    EVENT_PATH.unlink(missing_ok=True)
                    st.success("已清空行为日志。")
                    st.rerun()
        else:
            st.info("目前还没有行为日志。")

    with tab3:
        st.markdown(
            """
            **受试者链接：** 普通网页链接，不带 `?admin=1`。  
            **后台链接：** 在网页链接后加 `?admin=1`。  

            例如：
            - 后台：`https://your-app.streamlit.app/?admin=1`
            - 酒店官网受试者：`https://your-app.streamlit.app/?mode=hotel&freq=medium&fit=high&motive=high`
            - OTA受试者：`https://your-app.streamlit.app/?mode=ota&freq=medium&fit=high&motive=high`

            参数说明：
            - `mode=hotel` 或 `mode=ota`：酒店官网界面 / OTA界面
            - `freq=low / medium / three / high`：低频 / 中频 / 三频 / 高频
            - `fit=high / low`：高匹配 / 低匹配
            - `motive=high / low`：高利他动机 / 低利他动机

            所以你不需要每个实验条件都重新生成一个网页，只要改后台条件，然后复制生成出来的参数链接即可。

            当前版本为测试版。正式实验前建议继续加入：自动随机分组、最短作答时间、注意力检测、重复提交限制。
            """
        )


if is_admin_page():
    render_admin_panel()
else:
    render_participant_app()
